import itertools
cols={'1':np.ones_like(P),'P':P,'P2':P**2,'P3':P**3,'1/P':1/P,'t':t,'tP':t*P,'t2':t**2,'sin':np.sin(t),'cos':np.cos(t),'Pt2':P*t*t, 'P2t':P*P*t}
def fit(names):
    X=np.column_stack([cols[n] for n in names])
    c,res,_,_=np.linalg.lstsq(X,y,rcond=None)
    r=y-X@c
    return np.mean(r**2)/np.var(y), c
for k in [2,3,4]:
